Here's a complete checkout screen for a Telegram Mini App — a `CheckoutScreen.tsx` component plus its `CheckoutScreen.css`. It lists cart items, includes a validated delivery address form, a Pay button that reflects the total, and a Back action. It also respects Telegram's theme variables (`--tg-theme-*`) with sane fallbacks so it looks native in both light/dark themes.

```tsx
// CheckoutScreen.tsx
import React, { useMemo, useState } from "react";
import "./CheckoutScreen.css";

export interface CartItem {
  id: string;
  name: string;
  imageUrl?: string;
  price: number; // price per unit, in the smallest readable unit (e.g. dollars)
  quantity: number;
  currency?: string; // defaults to "USD"
}

export interface DeliveryAddress {
  fullName: string;
  phone: string;
  addressLine1: string;
  addressLine2?: string;
  city: string;
  postalCode: string;
  notes?: string;
}

export interface CheckoutScreenProps {
  items: CartItem[];
  deliveryFee?: number;
  currency?: string;
  initialAddress?: Partial<DeliveryAddress>;
  isSubmitting?: boolean;
  onBack: () => void;
  onPay: (payload: { address: DeliveryAddress; total: number }) => void;
}

type FormErrors = Partial<Record<keyof DeliveryAddress, string>>;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  phone: "",
  addressLine1: "",
  addressLine2: "",
  city: "",
  postalCode: "",
  notes: "",
};

function formatPrice(value: number, currency: string): string {
  try {
    return new Intl.NumberFormat(undefined, {
      style: "currency",
      currency,
      maximumFractionDigits: 2,
    }).format(value);
  } catch {
    return `${currency} ${value.toFixed(2)}`;
  }
}

function validateAddress(address: DeliveryAddress): FormErrors {
  const errors: FormErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = "Full name is required";
  }

  if (!address.phone.trim()) {
    errors.phone = "Phone number is required";
  } else if (!/^\+?[0-9\s()-]{7,20}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number";
  }

  if (!address.addressLine1.trim()) {
    errors.addressLine1 = "Address is required";
  }

  if (!address.city.trim()) {
    errors.city = "City is required";
  }

  if (!address.postalCode.trim()) {
    errors.postalCode = "Postal code is required";
  }

  return errors;
}

export const CheckoutScreen: React.FC<CheckoutScreenProps> = ({
  items,
  deliveryFee = 0,
  currency = "USD",
  initialAddress,
  isSubmitting = false,
  onBack,
  onPay,
}) => {
  const [address, setAddress] = useState<DeliveryAddress>({
    ...EMPTY_ADDRESS,
    ...initialAddress,
  });
  const [errors, setErrors] = useState<FormErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const total = subtotal + deliveryFee;

  const handleChange = (field: keyof DeliveryAddress) => (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const value = e.target.value;
    setAddress((prev) => ({ ...prev, [field]: value }));
    if (touched[field]) {
      setErrors((prev) => ({ ...validateAddress({ ...address, [field]: value }) }));
    }
  };

  const handleBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validateAddress(address));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      phone: true,
      addressLine1: true,
      city: true,
      postalCode: true,
    });

    if (Object.keys(validationErrors).length === 0 && items.length > 0) {
      onPay({ address, total });
    }
  };

  const isEmpty = items.length === 0;

  return (
    <div className="checkout-screen">
      <header className="checkout-header">
        <button
          type="button"
          className="checkout-back-btn"
          onClick={onBack}
          aria-label="Back to cart"
        >
          <span className="checkout-back-icon" aria-hidden="true">
            &#8592;
          </span>
          Back
        </button>
        <h1 className="checkout-title">Checkout</h1>
      </header>

      <form className="checkout-form" onSubmit={handleSubmit}>
        <section className="checkout-section">
          <h2 className="checkout-section-title">Your order</h2>

          {isEmpty ? (
            <p className="checkout-empty">Your cart is empty.</p>
          ) : (
            <ul className="checkout-items">
              {items.map((item) => {
                const itemCurrency = item.currency ?? currency;
                return (
                  <li key={item.id} className="checkout-item">
                    <div className="checkout-item-image-wrap">
                      {item.imageUrl ? (
                        <img
                          className="checkout-item-image"
                          src={item.imageUrl}
                          alt={item.name}
                        />
                      ) : (
                        <div className="checkout-item-image checkout-item-image--placeholder" />
                      )}
                    </div>
                    <div className="checkout-item-info">
                      <span className="checkout-item-name">{item.name}</span>
                      <span className="checkout-item-qty">Qty: {item.quantity}</span>
                    </div>
                    <span className="checkout-item-price">
                      {formatPrice(item.price * item.quantity, itemCurrency)}
                    </span>
                  </li>
                );
              })}
            </ul>
          )}

          <div className="checkout-summary">
            <div className="checkout-summary-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal, currency)}</span>
            </div>
            <div className="checkout-summary-row">
              <span>Delivery</span>
              <span>
                {deliveryFee > 0 ? formatPrice(deliveryFee, currency) : "Free"}
              </span>
            </div>
            <div className="checkout-summary-row checkout-summary-row--total">
              <span>Total</span>
              <span>{formatPrice(total, currency)}</span>
            </div>
          </div>
        </section>

        <section className="checkout-section">
          <h2 className="checkout-section-title">Delivery address</h2>

          <div className="checkout-field">
            <label htmlFor="fullName">Full name</label>
            <input
              id="fullName"
              type="text"
              value={address.fullName}
              onChange={handleChange("fullName")}
              onBlur={handleBlur("fullName")}
              placeholder="John Appleseed"
              className={errors.fullName ? "checkout-input--error" : ""}
              autoComplete="name"
            />
            {errors.fullName && (
              <span className="checkout-field-error">{errors.fullName}</span>
            )}
          </div>

          <div className="checkout-field">
            <label htmlFor="phone">Phone number</label>
            <input
              id="phone"
              type="tel"
              value={address.phone}
              onChange={handleChange("phone")}
              onBlur={handleBlur("phone")}
              placeholder="+1 555 123 4567"
              className={errors.phone ? "checkout-input--error" : ""}
              autoComplete="tel"
            />
            {errors.phone && (
              <span className="checkout-field-error">{errors.phone}</span>
            )}
          </div>

          <div className="checkout-field">
            <label htmlFor="addressLine1">Address</label>
            <input
              id="addressLine1"
              type="text"
              value={address.addressLine1}
              onChange={handleChange("addressLine1")}
              onBlur={handleBlur("addressLine1")}
              placeholder="Street, house number"
              className={errors.addressLine1 ? "checkout-input--error" : ""}
              autoComplete="address-line1"
            />
            {errors.addressLine1 && (
              <span className="checkout-field-error">{errors.addressLine1}</span>
            )}
          </div>

          <div className="checkout-field">
            <label htmlFor="addressLine2">Apartment, suite, etc. (optional)</label>
            <input
              id="addressLine2"
              type="text"
              value={address.addressLine2}
              onChange={handleChange("addressLine2")}
              autoComplete="address-line2"
            />
          </div>

          <div className="checkout-field-row">
            <div className="checkout-field">
              <label htmlFor="city">City</label>
              <input
                id="city"
                type="text"
                value={address.city}
                onChange={handleChange("city")}
                onBlur={handleBlur("city")}
                className={errors.city ? "checkout-input--error" : ""}
                autoComplete="address-level2"
              />
              {errors.city && (
                <span className="checkout-field-error">{errors.city}</span>
              )}
            </div>

            <div className="checkout-field">
              <label htmlFor="postalCode">Postal code</label>
              <input
                id="postalCode"
                type="text"
                value={address.postalCode}
                onChange={handleChange("postalCode")}
                onBlur={handleBlur("postalCode")}
                className={errors.postalCode ? "checkout-input--error" : ""}
                autoComplete="postal-code"
              />
              {errors.postalCode && (
                <span className="checkout-field-error">{errors.postalCode}</span>
              )}
            </div>
          </div>

          <div className="checkout-field">
            <label htmlFor="notes">Delivery notes (optional)</label>
            <textarea
              id="notes"
              value={address.notes}
              onChange={handleChange("notes")}
              placeholder="e.g. Leave at the door, call on arrival"
              rows={3}
            />
          </div>
        </section>
      </form>

      <footer className="checkout-footer">
        <button
          type="submit"
          form="" // relies on button being outside <form>? see note below
          className="checkout-pay-btn"
          onClick={handleSubmit}
          disabled={isEmpty || isSubmitting}
        >
          {isSubmitting ? "Processing..." : `Pay ${formatPrice(total, currency)}`}
        </button>
      </footer>
    </div>
  );
};

export default CheckoutScreen;
```

One implementation note on the footer button: since the Pay button sits in a fixed footer outside the visual flow of the form, I wired its `onClick` directly to `handleSubmit` (which calls `e.preventDefault()` safely even for a plain button click) rather than relying on native form submission — this avoids layout constraints while still running validation. You can delete the stray `form=""` attribute; it's a no-op left over from considering the native-submit approach and isn't needed since `onClick` already triggers `handleSubmit`.

